#include <Arduino.h>
#include <Wire.h>
#include <RTClib.h>

RTC_DS1307 rtc;
bool rtcReady = false;
const uint8_t numeral[10] = {
  0x3f, 0x06, 0x5b, 0x4f, 0x66,
  0x6d, 0x7d, 0x07, 0x7f, 0x6f
};

void disableDigits() {
  for (uint8_t p = 2; p <= 5; ++p) digitalWrite(p, LOW);
}

void showDigit(uint8_t position, uint8_t value) {
  disableDigits();
  uint8_t mask = numeral[value];
  for (uint8_t s = 0; s < 7; ++s) {
    digitalWrite(6 + s, (mask & (1U << s)) ? LOW : HIGH);
  }
  digitalWrite(2 + position, HIGH);
  delay(2);
  digitalWrite(2 + position, LOW);
}

void startRtc() {
  rtcReady = rtc.begin();
  if (rtcReady && !rtc.isrunning()) {
    Wire.beginTransmission(0x68);
    Wire.write((uint8_t)0);
    if (Wire.endTransmission() == 0) {
      Wire.requestFrom((uint8_t)0x68, (uint8_t)1);
      if (Wire.available()) {
        uint8_t seconds = (uint8_t)Wire.read() & 0x7f;
        Wire.beginTransmission(0x68);
        Wire.write((uint8_t)0);
        Wire.write(seconds);
        Wire.endTransmission();
      }
    }
  }
}

void setup() {
  Wire.begin();
  startRtc();
  for (uint8_t p = 2; p <= 13; ++p) {
    digitalWrite(p, p >= 6 ? HIGH : LOW);
    pinMode(p, OUTPUT);
  }
  digitalWrite(13, LOW);
}

void loop() {
  if (!rtcReady) {
    disableDigits();
    startRtc();
    delay(20);
    return;
  }
  DateTime now = rtc.now();
  uint8_t digits[4] = {
    (uint8_t)(now.hour() / 10), (uint8_t)(now.hour() % 10),
    (uint8_t)(now.minute() / 10), (uint8_t)(now.minute() % 10)
  };
  for (uint8_t i = 0; i < 4; ++i) showDigit(i, digits[i]);
}
